return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'Stvara sigurnosnu kopiju vaših WordPress datoteka i baze podataka u vašoj vlastitoj pohrani — Dropbox, Google Drive, Cloudflare R2, Amazon S3 ili bilo kojem spremniku kompatibilnom s S3 — vraća ih odjednom i uvozi sigurnosne kopije koje su izradili drugi priključci za sigurnosno kopiranje i migraciju.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'Sigurnosne kopije','Get Pro: schedules, several storages, encryption'=>'Nabavite Pro: rasporedi, više pohrana, enkripcija','Working…'=>'Obrada u tijeku…','Finished'=>'Završeno','Failed'=>'Neuspjelo','Cancelled'=>'Otkazano','Cancel'=>'Odustani','Restore'=>'Vrati','Delete'=>'Izbriši','Delete this backup from your storage? This cannot be undone.'=>'Obrisati ovu sigurnosnu kopiju iz vaše pohrane? Ova se radnja ne može poništiti.','No backups yet. Press “Back up now” to make the first one.'=>'Još nema sigurnosnih kopija. Pritisnite „Izradi sigurnosnu kopiju sada” kako biste izradili prvu.','Reading your storage…'=>'Očitavanje vaše pohrane…','a complete backup, as opposed to an incremental oneFull backup'=>'Potpuna sigurnosna kopija','a backup holding only what changed since an earlier oneIncremental backup'=>'Inkrementalna sigurnosna kopija','Encrypted'=>'Šifrirano','From another site'=>'S drugog web-mjesta','Database'=>'Baza podataka','Files'=>'Datoteke','Uploading %1$s: %2$s%%'=>'Prijenos %1$s: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'Prijavite se na Dropbox u otvorenom prozoru, a zatim zalijepite kod koji vam Dropbox prikazuje:','Saved.'=>'Spremljeno.','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'Ukloniti ovo odredište iz priključka? Sigurnosne kopije pohranjene u njemu neće se izbrisati.','Reload the page to see the restored site.'=>'Ponovno učitajte stranicu kako biste vidjeli vraćenu web-stranicu.','Storage'=>'Pohrana','Import & migrate'=>'Uvoz i migracija','Settings'=>'Postavke','Sections'=>'Odjeljci','Google Drive is connected.'=>'Google Drive je povezan.','Google Drive could not be connected.'=>'Povezivanje s uslugom Google Drive nije uspjelo.','Details'=>'Pojedinosti','Back up now'=>'Sigurnosno kopiraj sada','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'Sigurnosne kopije spremaju se u vaš vlastiti prostor za pohranu, a ne na ovaj poslužitelj. Najprije <a href="%s">povežite svoj prostor za pohranu</a>.','What to back up'=>'Što sigurnosno kopirati','Files and database'=>'Datoteke i baza podataka','Database only'=>'Samo baza podataka','Files only'=>'Samo datoteke','Note (optional)'=>'Napomena (neobavezno)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'Svaki se dio prenosi u vašu pohranu i uklanja s ovog poslužitelja prije izrade sljedećeg, tako da sigurnosna kopija nikada ne zauzima prostor na vašem smještaju.','Your backups'=>'Vaše sigurnosne kopije','Refresh'=>'Osvježi','Restore this backup'=>'Vrati ovu sigurnosnu kopiju','Passphrase'=>'Lozinka','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'Razumijem da ovo zamjenjuje datoteke i bazu podataka ove web-stranice onima iz sigurnosne kopije. Datoteke koje se ne nalaze u sigurnosnoj kopiji bit će zadržane.','Recent activity'=>'Nedavna aktivnost','Backup'=>'Sigurnosna kopija','Restore / import'=>'Vrati / uvezi','Running'=>'Pokrenuto','Your storage'=>'Vaša pohrana' . "\0" . 'Vaša odredišta za pohranu' . "\0" . 'Vaša odredišta za pohranu','No storage yet. Choose where your backups go below.'=>'Još nema pohrane. U nastavku odaberite kamo idu vaše sigurnosne kopije.','Ready'=>'Spremno','Not connected'=>'Nije povezano','Connect'=>'Poveži','Test'=>'Test','Edit'=>'Uredi','Remove'=>'Ukloni','Add storage'=>'Dodaj pohranu','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'Sigurnosne kopije idu na jedno odredište za pohranu. Da biste koristili drugo, uredite ili uklonite gore navedeno.','Kind of storage'=>'Vrsta pohrane','Name (for you)'=>'Naziv (za vas)','Provider'=>'Pružatelj usluge','Cloudflare account id'=>'ID Cloudflare računa','Endpoint address'=>'Adresa krajnje točke','Region'=>'Regija','Bucket'=>'Kanta','Access key id'=>'ID pristupnog ključa','Secret access key'=>'Tajni pristupni ključ','Leave empty to keep the saved key'=>'Ostavite prazno kako biste zadržali spremljeni ključ','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'Za Cloudflare R2: na Cloudflare nadzornoj ploči otvorite R2, stvorite bucket, zatim „Manage R2 API tokens” → stvorite token s pravima Object Read & Write za taj bucket te ovdje kopirajte access key id i secret.','Dropbox app key'=>'Ključ Dropbox aplikacije','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'Stvorite aplikaciju na dropbox.com/developers/apps (Scoped access, App folder) s dozvolama files.content.read, files.content.write i files.metadata.read te kopirajte njezin App key ovdje. Spremite, a zatim pritisnite Connect.','OAuth client id'=>'ID klijenta OAuth','OAuth client secret'=>'Tajna OAuth klijenta','Leave empty to keep the saved secret'=>'Ostavite prazno kako biste zadržali spremljenu tajnu','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'U Google Cloud Consoleu omogućite Google Drive API, a zatim stvorite OAuth klijent vrste „Web application” s ovom adresom kao ovlaštenim URI-jem za preusmjeravanje:','Save, then press Connect. The plugin only sees the files it creates.'=>'Spremite, a zatim pritisnite Spoji. Dodatak vidi samo datoteke koje sam stvori.','Folder inside the storage (optional)'=>'Mapa unutar pohrane (neobavezno)','Save storage'=>'Uštedite prostor za pohranu','Import a backup from another plugin or host'=>'Uvezite sigurnosnu kopiju iz drugog priključka ili poslužitelja','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'Uvezite web-mjesto iz sigurnosne kopije koju je izradio UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate ili iz bilo koje zip/tar arhive WordPress web-mjesta s njegovim .sql dumpom. Sadržaj odlazi u wp-content, a baza podataka zamjenjuje bazu podataka ovog web-mjesta; adrese se automatski mijenjaju u adrese ovog web-mjesta.','Upload from your computer'=>'Učitajte s vašeg računala','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'Odaberite sve datoteke sigurnosne kopije odjednom (UpdraftPlus stvara nekoliko). Velike datoteke šalju se u malim dijelovima, pa se ograničenje prijenosa vašeg poslužitelja ne primjenjuje.','Or from links (Google Drive, Dropbox or any download address)'=>'Ili s poveznica (Google Drive, Dropbox ili bilo koja adresa za preuzimanje)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'Jedna poveznica po retku. Za Google Drive i Dropbox podijelite datoteku sa „svima koji imaju poveznicu” i zalijepite tu poveznicu; nakon toga ponovno isključite dijeljenje.','Or a file already on this server'=>'Ili datoteka koja se već nalazi na ovom poslužitelju','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'Prenesite arhive putem FTP-a ili upravitelja datoteka vašeg poslužitelja u %s i ponovno učitajte ovu stranicu.','Or a deploy code from another site'=>'Ili kôd za postavljanje s drugog web-mjesta','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'Ako vam je drugo web-mjesto dalo kôd za implementaciju Zinn® Backups, zalijepite ga ovdje kako biste kopirali tu sigurnosnu kopiju na ovo web-mjesto bez dijeljenja ključeva za pohranu. Kôd radi nekoliko sati; postupajte s njim kao s lozinkom.','Passphrase (only if that backup is encrypted)'=>'Lozinka (samo ako je ta sigurnosna kopija šifrirana)','Import'=>'Uvezi','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'Razumijem da uvoz zamjenjuje sadržaj i bazu podataka ove web-stranice. Nakon toga se prijavite s računom s uvezene web-stranice.','Moving to Zinn® hosting?'=>'Prelazite na Zinn® hosting?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Zinn Digital® može premjestiti Vašu web-stranicu s Vašeg starog poslužitelja za Vas. Ako Vam Vaš stari poslužitelj ne pruža FTP, SSH ili pristup upravljačkoj ploči, instalirajte Zinn® Migrate na staru web-stranicu; on stvara jednu arhivu koju možete uvesti ovdje ili predati Zinn®-u.','What goes into a backup'=>'Što sadrži sigurnosna kopija','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'Uključite vlastite datoteke sustava WordPress (wp-admin, wp-includes). Obično nije potrebno: WordPress se uvijek može ponovno instalirati.','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'Također izostavite ove mape ili datoteke (jedna po retku, relativno u odnosu na mapu WordPress)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'Uvijek izostavljeno: predmemorije, privremeni prostor za ažuriranje i vlastite arhivske mape drugih priključaka za sigurnosno kopiranje:','Size of each part (MB)'=>'Veličina svakog dijela (MB)','Save settings'=>'Spremi postavke','A backup part could not be opened for writing. Check that wp-content has free space.'=>'Dio sigurnosne kopije nije se mogao otvoriti za pisanje. Provjerite ima li u mapi wp-content slobodnog prostora.','A backup part could not be written. Check that wp-content has free space.'=>'Dio sigurnosne kopije nije se mogao zapisati. Provjerite ima li u wp-content slobodnog prostora.','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'Prvo povežite odredište za pohranu na kartici Storage: sigurnosne kopije se čuvaju u vašoj vlastitoj pohrani, a ne na ovom poslužitelju.','Multisite networks are not supported yet.'=>'Mreže web-mjesta (multisite) još nisu podržane.','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'PHP ovog poslužitelja nema proširenje ZipArchive. Zatražite od svog pružatelja smještaja da ga omogući.','Starting'=>'Pokretanje','Listing files'=>'Dohvaćanje popisa datoteka','Backing up the database'=>'Izrada sigurnosne kopije baze podataka','Packing files'=>'Pakiranje datoteka','Uploading to your storage'=>'Prijenos u vašu pohranu','Finishing'=>'Dovršavanje','The backup reached an unknown stage.'=>'Sigurnosna kopija dosegla je nepoznatu fazu.','Backup %s started.'=>'Sigurnosno kopiranje stavke %s je započelo.','Found %1$s files (%2$s).'=>'Pronađeno datoteka: %1$s (%2$s).','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'Baza podataka: %1$d tablica, %2$s redaka, %3$s sažeto.','Backup complete: %1$s stored in %2$d destination.'=>'Sigurnosna kopija dovršena: %1$s pohranjeno na %2$d odredištu.' . "\0" . 'Sigurnosno kopiranje je dovršeno: %1$s pohranjeno na %2$d odredišta.' . "\0" . 'Sigurnosno kopiranje je dovršeno: %1$s pohranjeno na %2$d odredišta.','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'Neki dijelovi koji su već preneseni nisu se mogli ukloniti iz vaše pohrane; nalaze se u mapi nepotpunih sigurnosnih kopija i nikada se ne nude za vraćanje.','A storage destination was removed while the backup was running.'=>'Odredište za pohranu je uklonjeno tijekom izvođenja sigurnosne kopije.','That is not a backup folder.'=>'To nije mapa sigurnosne kopije.','That storage destination is no longer saved on this site.'=>'To odredište za pohranu više nije spremljeno na ovom web-mjestu.','Later incremental backups are built on this one. Delete those first.'=>'Kasnije inkrementalne sigurnosne kopije izgrađene su na ovoj. Prvo izbrišite njih.','This file is not an encrypted Zinn® Backups file.'=>'Ova datoteka nije šifrirana Zinn® Backups datoteka.','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'Sigurnosna kopija nije se mogla dešifrirati: zaporka je pogrešna ili je datoteka oštećena.','The encrypted backup file is incomplete.'=>'Šifrirana sigurnosna kopija nije potpuna.','The database file could not be written. Check that wp-content has free space.'=>'Datoteku baze podataka nije bilo moguće zapisati. Provjerite ima li mapa wp-content slobodnog prostora.','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'To nije kôd za implementaciju. Kôd za implementaciju počinje s zbdeploy1.','That deploy code is damaged. Copy it again from the other site.'=>'Taj kôd za implementaciju je oštećen. Ponovno ga kopirajte s drugog web-mjesta.','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'Kôd za implementaciju je istekao ili je njegova sigurnosna kopija izbrisana. Izradite novi kôd na drugom web-mjestu.','That deploy code does not point at a Zinn® Backups backup.'=>'Taj kod za implementaciju ne upućuje na sigurnosnu kopiju Zinn® Backups.','The deploy code has expired. Make a new code on the other site.'=>'Kôd za implementaciju je istekao. Napravite novi kôd na drugom web-mjestu.','The server stopped honouring partial downloads. Start the import again.'=>'Poslužitelj je prestao podržavati djelomična preuzimanja. Pokrenite uvoz ponovno.','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'Poveznica je otvorila web-stranicu umjesto datoteke. Za Google Drive i Dropbox podijelite datoteku s opcijom „svatko s poveznicom” i zalijepite tu poveznicu.','The link answered with HTTP %d.'=>'Poveznica je odgovorila s HTTP %d.','The file list could not be written.'=>'Nije bilo moguće zapisati popis datoteka.','The storage service could not be reached: %s'=>'Nije moguće dohvatiti uslugu pohrane: %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s je odgovorio s HTTP %2$d: %3$s','no details given'=>'Nisu navedeni detalji','You are not allowed to manage backups.'=>'Nemate dopuštenje za upravljanje sigurnosnim kopijama.','Tick the box to confirm that the restore replaces this site’s files and database.'=>'Označite okvir kako biste potvrdili da vraćanje zamjenjuje datoteke i bazu podataka ovog web-mjesta.','Save the destination first.'=>'Prvo spremite odredište.','Connected: a test file was written and removed.'=>'Povezano: testna datoteka je zapisana i uklonjena.','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'Prvo unesite ključ svoje Dropbox aplikacije (pogledajte korake pored obrasca).','This kind of storage does not sign in.'=>'Ova vrsta pohrane se ne prijavljuje.','The sign-in expired. Press Connect again.'=>'Prijava je istekla. Ponovno pritisnite Poveži.','Dropbox is connected.'=>'Dropbox je povezan.','Settings saved.'=>'Postavke spremljene.','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'Drugo sigurnosno kopiranje, vraćanje ili uvoz je u tijeku. Pričekajte da završi ili ga otkažite.','The upload was not started properly. Start again.'=>'Prijenos nije ispravno započeo. Započnite ponovno.','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'Dio nije stigao. Vaš poslužitelj možda ograničava veličinu prijenosa; pokušajte ponovo.','Tick the box to confirm that the import replaces this site’s content and database.'=>'Označite okvir kako biste potvrdili da uvoz zamjenjuje sadržaj i bazu podataka ove web-stranice.','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'Odaberite arhivu za uvoz: prenesite je, zalijepite poveznicu ili odaberite arhivu iz mape za uvoz.','Hosting customer? Get %1$d%% off %2$s'=>'Korisnik hostinga? Ostvarite %1$d%% popusta na %2$s','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'Kao korisnik Zinn Digital® hostinga dobivate osobni kôd za %d%% popusta na svoju prvu uplatu. Obnove su po uobičajenoj cijeni.','Get my %d%% code and go to checkout'=>'Preuzmite moj kod za %d%% i idite na blagajnu','Sorry, you are not allowed to do that.'=>'Žao nam je, nemate dopuštenje za to.','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'Ovaj popust namijenjen je korisnicima s plaćenim hosting paketom s urednim statusom. Besplatna probna razdoblja ne ispunjavaju uvjete.','You have already used your hosting-customer discount for this plugin.'=>'Već ste iskoristili svoj popust za korisnike hostinga za ovaj priključak.','We could not get your code just now. Please try again in a few minutes.'=>'Upravo nismo uspjeli dohvatiti Vaš kôd. Molimo pokušajte ponovno za nekoliko minuta.','Reading the backup'=>'Čitanje sigurnosne kopije','Downloading the archive'=>'Preuzimanje arhive','Recognising the archive'=>'Prepoznavanje arhive','Restoring files'=>'Vraćanje datoteka','Downloading the database'=>'Preuzimanje baze podataka','Restoring the database'=>'Vraćanje baze podataka','Updating the site address'=>'Ažuriranje adrese web-mjesta','Switching to the restored database'=>'Prebacivanje na vraćenu bazu podataka','The restore reached an unknown stage.'=>'Vraćanje je doseglo nepoznatu fazu.','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'Ova mapa ne sadrži potpunu sigurnosnu kopiju Zinn® Backups (nedostaje manifest).','This backup is encrypted. Enter its passphrase to restore it.'=>'Ova sigurnosna kopija je šifrirana. Unesite njezinu lozinku kako biste je vratili.','This incremental backup needs backup %s, which is no longer in the storage.'=>'Ova inkrementalna sigurnosna kopija zahtijeva sigurnosnu kopiju %s, koja se više ne nalazi u pohrani.','Restoring the backup of %1$s (%2$d file parts).'=>'Vraćanje sigurnosne kopije stavke %1$s (%2$d dijelova datoteke).','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'Nije moguće prebrisati datoteku %1$s jer ovom web-mjestu nije dopušteno mijenjati je, te je ostavljena takva kakva jest: %2$s' . "\0" . '%1$s datoteka nije se moglo prepisati jer ovoj web-stranici nije dopušteno mijenjati ih, te su ostavljene kakve jesu: %2$s' . "\0" . '%1$s datoteka nije se moglo prepisati jer ovoj web-stranici nije dopušteno mijenjati ih, te su ostavljene kakve jesu: %2$s','Restored %s files.'=>'Vraćeno je %s datoteka.','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'%s se nakon preuzimanja ne podudara sa svojim kontrolnim zbrojem. Kopija u pohrani možda je oštećena.','%s did not arrive. Upload it again.'=>'%s nije stigao. Učitajte ga ponovno.','Recognised: %s.'=>'Prepoznato: %s.','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'Uvezeno je %1$s datoteka u wp-content (%2$s izostavljeno: predmemorije, drop-in dodaci i mape ostalih dodataka za sigurnosne kopije).','The archive has no database dump, so only files were imported.'=>'Arhiva ne sadrži izvoz baze podataka, pa su uvezenje samo datoteke.','Database restored into %d temporary tables.'=>'Baza podataka vraćena je u %d privremenih tablica.','%s has no WordPress tables in it and was skipped.'=>'%s ne sadrži WordPress tablice i preskočen je.','The backup’s database has no WordPress tables, so nothing was replaced.'=>'Baza podataka sigurnosne kopije ne sadrži tablice sustava WordPress, pa ništa nije zamijenjeno.','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'Ova sigurnosna kopija pripada mreži više web-mjesta (multisite). Vraćanje mreže na jedno web-mjesto nije podržano.','Moving the content from %1$s to %2$s.'=>'Premještanje sadržaja s %1$s na %2$s.','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'Vraćanje je dovršeno. Ako ste odjavljeni, prijavite se računom s vraćenog web-mjesta.','Restore complete.'=>'Vraćanje dovršeno.','%1$s — trying again in %2$d seconds.'=>'%1$s — ponovni pokušaj za %2$d sekundi.','Cancelled.'=>'Otkazano.','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'Sigurnosne kopije idu na jedno odredište za pohranu. Uredite ili uklonite postojeće kako biste koristili drugo.','The database file could not be opened.'=>'Datoteku baze podataka nije moguće otvoriti.','The database refused a statement from the backup: %1$s (%2$s…)'=>'Baza podataka odbila je naredbu iz sigurnosne kopije: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'Vraćene tablice nisu se mogle zamijeniti: %s. Vaše web-mjesto ostalo je nepromijenjeno.','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'Nema mape s pravom pisanja za privremene sigurnosne kopije. Omogućite pisanje u mapu wp-content i pokušajte ponovno.','Could not create a folder for this job.'=>'Nije uspjelo stvaranje mape za ovaj zadatak.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnički vodiči','Read the %s user guide'=>'Pročitajte korisnički vodič za %s','Hide this'=>'Sakrij ovo','Zinn® hosting for WordPress'=>'Zinn® smještaj za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, svakodnevne sigurnosne kopije, besplatna migracija i upravljačka ploča stvorena za osobe koje vode više od jedne web-stranice.','The Zinn® marketplace'=>'Trgovina Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajte etablirane web-stranice, domene i postavljanja poveznica, uz sigurno čuvanje novca dok obje strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — angažirajte ljude koji se time profesionalno bave','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište slobodnih zanimanja: pregledajte više od 10.000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka ili objavite projekt i omogućite im davanje ponuda.','See the Zinn Digital® release notes.'=>'Pogledajte bilješke o izdanju za Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Usluga ažuriranja Zinn® nije izdala poveznicu za preuzimanje ovog ažuriranja. Provjerite može li ovo web-mjesto pristupiti platformi Zinn®, a zatim pokušajte ponovno.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Ažuriranje se nije moglo preuzeti s usluge ažuriranja Zinn® (%s). Pokušajte ponovno za nekoliko minuta.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo provjeru integriteta i nije instalirano.','The zip archive could not be opened. It may be damaged or incomplete.'=>'Zip arhivu nije bilo moguće otvoriti. Možda je oštećena ili nepotpuna.','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'Ova .wpress datoteka koristi format koji ne možemo pročitati (možda je komprimirana ili šifrirana putem All-in-One WP Migration). Izvezite je ponovo bez šifriranja.','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'Ovo je Duplicator „DupArchive” (.daf) datoteka. U dodatku Duplicator ponovno izradite paket s formatom arhive postavljenim na ZIP, a zatim ga uvezite.','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'Ova sigurnosna kopija baze podataka UpdraftPlus je šifrirana. Dešifrirajte je u dodatku UpdraftPlus (ili isključite šifriranje baze podataka i ponovno napravite sigurnosnu kopiju), a zatim je uvezite.','Database dump'=>'Dump baze podataka','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'%s nije arhiva sigurnosne kopije koju možemo pročitati (zip, tar, tar.gz, .wpress, .sql ili .sql.gz).','Website archive'=>'Arhiva web-stranice','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'%s ne sadrži nikakav WordPress sadržaj (nema mapu wp-content niti sigurnosnu kopiju baze podataka).','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'Ova .wpress datoteka je šifrirana ili komprimirana pomoću dodatka All-in-One WP Migration. Izvezite je ponovno s isključenim šifriranjem i kompresijom, a zatim je uvezite.','Other S3-compatible storage'=>'Druga pohrana kompatibilna s S3','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 ili kompatibilno s S3','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'Ključevi pohrane nisu se mogli pročitati na ovom web-mjestu. Ponovno unesite tajni ključ na kartici Pohrana.','This kind of storage is not known.'=>'Ova vrsta pohrane nije poznata.','Choose a kind of storage.'=>'Odaberite vrstu pohrane.','Enter the bucket name and the access key.'=>'Unesite naziv spremnika i pristupni ključ.','Enter your Cloudflare account id (or the full R2 endpoint).'=>'Unesite ID svog Cloudflare računa (ili punu R2 krajnju točku).','Enter the endpoint address of your storage.'=>'Unesite adresu krajnje točke svoje pohrane.','Enter the OAuth client id from your Google Cloud project.'=>'Unesite OAuth client id iz svog projekta Google Cloud.','Dropbox did not return a refresh token. Start the connection again.'=>'Dropbox nije vratio token za osvježavanje. Ponovno pokrenite povezivanje.','Dropbox is not connected. Connect it again on the Storage tab.'=>'Dropbox nije povezan. Ponovno ga povežite na kartici Pohrana.','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Google nije vratio token za osvježavanje. Uklonite ovo web-mjesto iz pristupa trećih strana na svojem Google računu i ponovno se povežite.','That file is not in Google Drive any more.'=>'Ta datoteka više nije na Google Driveu.','Google Drive is not connected. Connect it again on the Storage tab.'=>'Google Drive nije povezan. Ponovno ga povežite na kartici Pohrana.','The storage service did not start the upload.'=>'Pohrana nije pokrenula prijenos.','The storage service sent a reply that could not be read.'=>'Pohrambena usluga poslala je odgovor koji se nije mogao pročitati.','A temporary backup file could not be read.'=>'Privremena datoteka sigurnosne kopije nije se mogla pročitati.','A deploy link is read-only.'=>'Poveznica za postavljanje je samo za čitanje.','The deploy code has no link for a file this backup needs.'=>'Kod za postavljanje nema poveznicu za datoteku koja je potrebna ovoj sigurnosnoj kopiji.','The deploy link'=>'Poveznica za implementaciju']];